static std::vector<std::string> lines(ByteSpan b){std::string s((const char*)b.data,(size_t)b.size);std::vector<std::string>out;std::stringstream ss(s);std::string x;while(std::getline(ss,x)){if(!x.empty()&&x.back()=='\r')x.pop_back();if(!x.empty())out.push_back(x);}return out;}static bool exact_kv(const std::vector<std::string>&ls,std::string_view magic,const std::vector<std::string>&keys,std::map<std::string,std::string>*out){if(ls.size()!=keys.size()+1||ls[0]!=magic)return false;for(size_t i=0;i<keys.size();i++){auto p=ls[i+1].find('=');if(p==std::string::npos||ls[i+1].substr(0,p)!=keys[i])return false;(*out)[keys[i]]=ls[i+1].substr(p+1);}return true;}
Status parse_historical_fixture(ByteSpan b,HistoricalFixture*out){if(!out||!valid_utf8(b))return Status::InvalidUtf8;std::map<std::string,std::string>m;std::vector<std::string>k={"source_id","author","title","year","witness_id","passage_id","locator","claim_id","subject_id","predicate","claim_class","epistemic","scope","payload"};if(!exact_kv(lines(b),"LHF1",k,&m))return Status::ParseError;if(m["payload"].find("||")!=std::string::npos)return Status::ParseError;for(auto id:{"source_id","witness_id","passage_id","claim_id","subject_id"})if(!valid_semantic_id(m[id]))return Status::ParseError;*out={m["source_id"],m["author"],m["title"],m["year"],m["witness_id"],m["passage_id"],m["locator"],m["claim_id"],m["subject_id"],m["predicate"],m["claim_class"],m["epistemic"],m["scope"],m["payload"]};return out->epistemic=="REPORTED"?Status::Ok:Status::EpistemicAmplification;}Status parse_genesis_fixture(ByteSpan b,GenesisFixture*out){if(!out||!valid_utf8(b))return Status::InvalidUtf8;std::map<std::string,std::string>m;std::vector<std::string>k={"implementation_id","court_id","scope","obs_receiver_id","receiver_content","obs_write_id","write_count","obs_duplicate_id","duplicate_second_effect","claim_id"};if(!exact_kv(lines(b),"LGF1",k,&m))return Status::ParseError;for(auto id:{"implementation_id","court_id","obs_receiver_id","obs_write_id","obs_duplicate_id","claim_id"})if(!valid_semantic_id(m[id]))return Status::ParseError;try{*out={m["implementation_id"],m["court_id"],m["scope"],m["obs_receiver_id"],m["receiver_content"],m["obs_write_id"],std::stoull(m["write_count"]),m["obs_duplicate_id"],std::stoull(m["duplicate_second_effect"]),m["claim_id"]};}catch(...){return Status::ParseError;}return Status::Ok;}
static Status finish(LgoBuilder&b,Buffer*out){return lgo_finish(&b,out,nullptr);}static Status add_exact_node(ObjectStore*s,Ledger*l,GraphState*g,Buffer&b,std::string_view id,bool*changed){Digest256 d{};auto st=graph_add_node(s,l,g,{b.data(),(u64)b.size()},&d);if(st==Status::NodeExists){if(changed)*changed=false;return Status::Ok;}if(st==Status::Ok&&changed)*changed=true;(void)id;return st;}static Status add_exact_edge(ObjectStore*s,Ledger*l,GraphState*g,std::string_view a,RelationCode r,std::string_view b,std::string_view scope,bool*changed){LgoBuilder x{};lgo_begin(&x);lgo_add_u64(&x,F_RECORD_KIND,(u64)RecordKind::EDGE);if(!scope.empty())lgo_add_utf8(&x,F_SCOPE,scope);lgo_add_utf8(&x,F_REF_A_ID,a);lgo_add_utf8(&x,F_REF_B_ID,b);lgo_add_u64(&x,F_RELATION_CODE,(u64)r);Buffer o;finish(x,&o);auto st=graph_add_edge(s,l,g,{o.data(),(u64)o.size()},nullptr);if(st==Status::EdgeExists){if(changed)*changed=false;return Status::Ok;}if(st==Status::Ok&&changed)*changed=true;return st;}Status record_rejection(ObjectStore*s,Ledger*l,GraphState*g,const Digest256&input,u64 reason,std::string_view detail,Digest256*out){LgoBuilder b{};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,(u64)RecordKind::REJECTION);lgo_add_digest(&b,F_INPUT_DIGEST,input);lgo_add_u64(&b,F_REJECTION_REASON,reason);lgo_add_utf8(&b,F_REJECTION_DETAIL,detail);Buffer o;finish(b,&o);return graph_record_rejection(s,l,g,{o.data(),(u64)o.size()},out);}
Status ingest_historical(ObjectStore*s,Ledger*l,GraphState*g,ByteSpan raw,CompilerCapsule*c){if(!s||!l||!g||!c)return Status::InvalidArgument;*c=CompilerCapsule{};c->input_digest=sha256(raw);graph_root(*g,&c->graph_root_before);HistoricalFixture f{};auto st=parse_historical_fixture(raw,&f);if(st!=Status::Ok){record_rejection(s,l,g,c->input_digest,st==Status::EpistemicAmplification?9:4,status_name(st),nullptr);c->disposition=IntakeDisposition::Rejected;graph_root(*g,&c->graph_root_after);return st;}Digest256 rawd{};if((st=blob_put(s,raw,&rawd))!=Status::Ok)return st;bool any=false,ch=false;Buffer o;LgoBuilder b{};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::SOURCE);lgo_add_utf8(&b,F_SEMANTIC_ID,f.source_id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_utf8(&b,F_TITLE,f.title);lgo_add_utf8(&b,F_ATTRIBUTION,f.author);lgo_add_utf8(&b,F_SOURCE_CLASS,"BOOK");lgo_add_utf8(&b,F_TIME_SCOPE,f.year);finish(b,&o);if((st=add_exact_node(s,l,g,o,f.source_id,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(f.source_id);b={};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::WITNESS);lgo_add_utf8(&b,F_SEMANTIC_ID,f.witness_id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_digest(&b,F_OBJECT_DIGEST,rawd);lgo_add_utf8(&b,F_REF_A_ID,f.source_id);finish(b,&o);if((st=add_exact_node(s,l,g,o,f.witness_id,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(f.witness_id);b={};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::PASSAGE);lgo_add_utf8(&b,F_SEMANTIC_ID,f.passage_id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_digest(&b,F_OBJECT_DIGEST,rawd);lgo_add_utf8(&b,F_LOCATOR,f.locator);lgo_add_utf8(&b,F_VALUE_TEXT,f.payload);lgo_add_utf8(&b,F_REF_A_ID,f.witness_id);finish(b,&o);if((st=add_exact_node(s,l,g,o,f.passage_id,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(f.passage_id);b={};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::CLAIM);lgo_add_utf8(&b,F_SEMANTIC_ID,f.claim_id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_u64(&b,F_EPISTEMIC_STATE,(u64)Epistemic::REPORTED);lgo_add_utf8(&b,F_SCOPE,f.scope);lgo_add_utf8(&b,F_VALUE_TEXT,f.payload);lgo_add_utf8(&b,F_CLAIM_CLASS,f.claim_class);lgo_add_utf8(&b,F_PROVENANCE_ID,f.passage_id);lgo_add_utf8(&b,F_TIME_SCOPE,f.year);lgo_add_utf8(&b,F_SUBJECT_ID,f.subject_id);lgo_add_utf8(&b,F_PREDICATE,f.predicate);lgo_add_u64(&b,F_VALUE_KIND,(u64)ValueKind::TEXT);finish(b,&o);if((st=add_exact_node(s,l,g,o,f.claim_id,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(f.claim_id);if((st=add_exact_edge(s,l,g,f.witness_id,RelationCode::WITNESS_OF,f.source_id,"",&ch))!=Status::Ok)return st;any|=ch;if((st=add_exact_edge(s,l,g,f.passage_id,RelationCode::EXTRACTED_FROM,f.witness_id,"",&ch))!=Status::Ok)return st;any|=ch;if((st=add_exact_edge(s,l,g,f.passage_id,RelationCode::ASSERTS,f.claim_id,f.scope,&ch))!=Status::Ok)return st;any|=ch;c->disposition=any?IntakeDisposition::Admitted:IntakeDisposition::AlreadyAdmitted;graph_root(*g,&c->graph_root_after);return Status::Ok;}
Status ingest_genesis(ObjectStore*s,Ledger*l,GraphState*g,ByteSpan raw,CompilerCapsule*c){if(!s||!l||!g||!c)return Status::InvalidArgument;*c=CompilerCapsule{};c->input_digest=sha256(raw);graph_root(*g,&c->graph_root_before);GenesisFixture f{};auto st=parse_genesis_fixture(raw,&f);if(st!=Status::Ok){record_rejection(s,l,g,c->input_digest,4,status_name(st),nullptr);c->disposition=IntakeDisposition::Rejected;graph_root(*g,&c->graph_root_after);return st;}Digest256 rawd{};if((st=blob_put(s,raw,&rawd))!=Status::Ok)return st;(void)rawd;bool any=false,ch=false;Buffer o;LgoBuilder b{};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::IMPLEMENTATION);lgo_add_utf8(&b,F_SEMANTIC_ID,f.implementation_id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_utf8(&b,F_TITLE,"Genesis MVS-001");lgo_add_utf8(&b,F_SCOPE,f.scope);finish(b,&o);if((st=add_exact_node(s,l,g,o,f.implementation_id,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(f.implementation_id);b={};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::COURT);lgo_add_utf8(&b,F_SEMANTIC_ID,f.court_id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_utf8(&b,F_TITLE,"Genesis hard-crash court");lgo_add_utf8(&b,F_SCOPE,f.scope);lgo_add_utf8(&b,F_REF_A_ID,f.implementation_id);lgo_add_u64(&b,F_COURT_DENOMINATOR,1);finish(b,&o);if((st=add_exact_node(s,l,g,o,f.court_id,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(f.court_id);auto addobs=[&](const std::string&id,const std::string&pred,ValueKind vk,const std::string&text,u64 num)->Status{LgoBuilder q{};Buffer z;lgo_begin(&q);lgo_add_u64(&q,F_RECORD_KIND,1);lgo_add_u64(&q,F_NODE_TYPE,(u64)NodeType::OBSERVATION);lgo_add_utf8(&q,F_SEMANTIC_ID,id);lgo_add_u64(&q,F_REVISION,1);lgo_add_u64(&q,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_utf8(&q,F_SCOPE,f.scope);if(vk==ValueKind::TEXT)lgo_add_utf8(&q,F_VALUE_TEXT,text);else lgo_add_u64(&q,F_VALUE_U64,num);lgo_add_utf8(&q,F_REF_A_ID,f.court_id);lgo_add_utf8(&q,F_PREDICATE,pred);lgo_add_u64(&q,F_VALUE_KIND,(u64)vk);finish(q,&z);bool cc=false;auto sx=add_exact_node(s,l,g,z,id,&cc);any|=cc;if(cc)c->admitted_ids.push_back(id);return sx;};if((st=addobs(f.obs_receiver_id,"receiver_content",ValueKind::TEXT,f.receiver_content,0))!=Status::Ok)return st;if((st=addobs(f.obs_write_id,"write_count",ValueKind::U64,"",f.write_count))!=Status::Ok)return st;if((st=addobs(f.obs_duplicate_id,"duplicate_second_effect",ValueKind::U64,"",f.duplicate_second_effect))!=Status::Ok)return st;const std::string claimText="Under the hosted-Windows canary represented by this fixture, the receiver reached the desired state after crash recovery without a second physical write.";b={};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::CLAIM);lgo_add_utf8(&b,F_SEMANTIC_ID,f.claim_id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_u64(&b,F_EPISTEMIC_STATE,(u64)Epistemic::TESTED);lgo_add_utf8(&b,F_SCOPE,f.scope);lgo_add_utf8(&b,F_VALUE_TEXT,claimText);lgo_add_utf8(&b,F_CLAIM_CLASS,"ENGINEERING_SCOPED_OUTCOME");lgo_add_utf8(&b,F_PROVENANCE_ID,f.court_id);lgo_add_utf8(&b,F_SUBJECT_ID,f.implementation_id);lgo_add_utf8(&b,F_PREDICATE,"hardcrash_outcome");lgo_add_u64(&b,F_VALUE_KIND,(u64)ValueKind::TEXT);finish(b,&o);if((st=add_exact_node(s,l,g,o,f.claim_id,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(f.claim_id);for(auto oid:{f.obs_receiver_id,f.obs_write_id,f.obs_duplicate_id}){std::string eid="EVD-"+oid+"-"+f.claim_id;LgoBuilder q{};Buffer z;lgo_begin(&q);lgo_add_u64(&q,F_RECORD_KIND,1);lgo_add_u64(&q,F_NODE_TYPE,(u64)NodeType::EVIDENCE);lgo_add_utf8(&q,F_SEMANTIC_ID,eid);lgo_add_u64(&q,F_REVISION,1);lgo_add_u64(&q,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_utf8(&q,F_SCOPE,f.scope);lgo_add_utf8(&q,F_REF_A_ID,oid);lgo_add_utf8(&q,F_REF_B_ID,f.claim_id);lgo_add_u64(&q,F_RELATION_CODE,(u64)RelationCode::SUPPORTS);finish(q,&z);if((st=add_exact_node(s,l,g,z,eid,&ch))!=Status::Ok)return st;any|=ch;if(ch)c->admitted_ids.push_back(eid);}if((st=add_exact_edge(s,l,g,f.court_id,RelationCode::TESTS,f.implementation_id,f.scope,&ch))!=Status::Ok)return st;any|=ch;for(auto oid:{f.obs_receiver_id,f.obs_write_id,f.obs_duplicate_id}){if((st=add_exact_edge(s,l,g,f.court_id,RelationCode::OBSERVES,oid,f.scope,&ch))!=Status::Ok)return st;any|=ch;if((st=add_exact_edge(s,l,g,oid,RelationCode::SUPPORTS,f.claim_id,f.scope,&ch))!=Status::Ok)return st;any|=ch;}if((st=add_exact_edge(s,l,g,f.claim_id,RelationCode::SCOPED_TO,f.implementation_id,f.scope,&ch))!=Status::Ok)return st;any|=ch;c->disposition=any?IntakeDisposition::Admitted:IntakeDisposition::AlreadyAdmitted;graph_root(*g,&c->graph_root_after);return Status::Ok;}
